import{_ as e,o as t,c as a,ag as i}from"./chunks/framework.D9ghT4bC.js";const m=JSON.parse('{"title":"开源中的翻译、模组与模组自由","description":"","frontmatter":{},"headers":[],"relativePath":"zh/Developers/Translations,-mods,-and-modding-freedom-in-Open-Source.md","filePath":"zh/Developers/Translations,-mods,-and-modding-freedom-in-Open-Source.md"}'),n={name:"zh/Developers/Translations,-mods,-and-modding-freedom-in-Open-Source.md"};function r(l,o,s,u,c,d){return t(),a("div",null,[...o[0]||(o[0]=[i('<h1 id="开源中的翻译、模组与模组自由" tabindex="-1">开源中的翻译、模组与模组自由 <a class="header-anchor" href="#开源中的翻译、模组与模组自由" aria-label="Permalink to &quot;开源中的翻译、模组与模组自由&quot;">​</a></h1><p>Unciv 本质上是对《文明5》的复刻，这意味着在机制层面几乎天然没有多少创新空间。 在 UI 方面，这里没有任何东西是没被做过几十次、而且做得精致得多的。 然而，有一个领域 Unciv 是开创性的：翻译的可及性、模组的可能性空间，以及两者之间的关系。</p><h2 id="翻译" tabindex="-1">翻译 <a class="header-anchor" href="#翻译" aria-label="Permalink to &quot;翻译&quot;">​</a></h2><h3 id="翻译流程" tabindex="-1">翻译流程 <a class="header-anchor" href="#翻译流程" aria-label="Permalink to &quot;翻译流程&quot;">​</a></h3><p>让我们从翻译说起。这肯定是已经解决的问题，对吧？源文本 + 语言 = 翻译文本，这些信息需要放进文件里让游戏读取。我们和 Firaxis 之类公司有什么不同？</p><p>有几件事，但最重要的是：这是开源游戏，因此<em>翻译</em>也是开源的。 这意味着翻译者都是业余爱好者，且没有<em>义务</em>翻译——如果翻译很困难，他们干脆就不翻了。</p><p>业余者会犯错，所以错误必须容易被发现，这一点至关重要。这意味着像 &quot;translation key&quot; 这样的格式——例如 <code>DIPLOMACY_GREETING = Siamo lieti di fare la vostra conoscenza.</code>——远不如 <code>A pleasure to meet you. = Siamo lieti di fare la vostra conoscenza.</code> 有效。这种格式既便于翻译（一眼就知道要翻译什么），也便于真正的协作。</p><p>我们经常收到的一个建议（来自对项目不太熟悉的人）是&quot;用网站做翻译&quot;。对小型开源游戏来说这不是坏建议，但有多个缺点，而（目前）没有任何翻译网站的优势足以抵消：</p><ol><li><strong>测试</strong>。目前翻译要经过一系列测试验证——后面细说！这让某些语言改动被接受、另一些被拒绝，而且都在同一个平台用同一套测试。外部翻译工具做不到。</li><li><strong>历史与修订</strong>。这正是 Git 的用武之地，世界上没有比它更好的了。单凭这一点就……</li><li><strong>发布周期</strong>。我们大约每半周发布一个版本，如果每次游戏内改动都要上传到翻译网站、每次发布都要下载，那就是额外的工作。有些网站可以自动化——大多数不行。</li><li><strong>讨论</strong>。大多数众包翻译网站不允许对翻译进行讨论和修正。Github 让每条翻译都成为协作成果。</li><li><strong>批量改动</strong>。如果我们要改翻译源文本但保留各种译文（比如把 &quot;Gold from trade routes +[amount]%&quot; 改成 &quot;+[amount]% Gold from trade routes&quot;），只要所有翻译文件都在 Git 里，一分钟就能搞定。如果在外部的，就难说了。</li></ol><p>以下是我们过去踩过的一些坑：</p><ul><li>把所有语言放进同一个文件（&quot;一个巨大的翻译字典&quot;）——多人同时为不同语言编辑这个文件时会互相冲突。拆成不同文件便于管理。</li><li>使用 json——json 对机器很好，但对人就没那么友好，人很容易犯错。json 格式出奇地挑剔，少一个结尾引号整个文件就读不了了。</li></ul><p>我们最终选择的格式是每种语言一个文件，用 &quot; = &quot; 分隔以利视觉分离，使用 .properties 格式。以 # 开头的行视为注释，所以我们可以为翻译者添加注释。</p><h3 id="构建翻译文件" tabindex="-1">构建翻译文件 <a class="header-anchor" href="#构建翻译文件" aria-label="Permalink to &quot;构建翻译文件&quot;">​</a></h3><p>如前所述，Unciv 大约每半周发布一个版本，而这些改动经常包含新对象或新 UI 元素。我们如何保持所有翻译文件最新？</p><p>在 Unciv 中，所有对象数据都以 json 格式存储。这让我们可以遍历所有对象（无论类型），提取各种文本字段（字符串或字符串列表）。我们通过保存所有已添加的翻译文本来避免重复，并用<em>现有</em>翻译为在 json 文件中找到的每条翻译 &quot;key&quot; 填充 &quot;value&quot;。</p><p>由于我们每次都会重建整个翻译文件，目前翻译者无法为后来的翻译者保留自己的注释。 但另一方面，由于对每行我们添加的内容都已经知道它是否已翻译，我们可以为每条未翻译的行前加 <code># Requires translation</code> 标记，这能帮助那些几乎全翻译完的语言的翻译者用 ctrl+f 轻松定位需要翻译的新词条（当然下次重建文件时标记会消失）。</p><p>由于有些 UI 文本不属于任何特定对象（比如 &quot;Start new game&quot;），我们有一个独立的 template.properties 文件来放那些不在 json 文件里的待翻译文本。与添加对象不同（开发者完全不需要碰翻译文件，因为都是自动关联的），添加带新文本的 UI 元素时，开发者需要记得把文本加到 template.properties 里。</p><h3 id="翻译占位符" tabindex="-1">翻译占位符 <a class="header-anchor" href="#翻译占位符" aria-label="Permalink to &quot;翻译占位符&quot;">​</a></h3><p>这对具体的文本到文本翻译很有效，但翻译 &quot;A Temple has been built in Rome&quot; 怎么办？同一个模板可能对应任何建筑名、任何城市名！</p><p>我们用占位符解决，看起来像这样：<code>[construction] has been built in [cityName] = [cityName] ha costruito [construction]</code>。 如你所见，参数的<em>位置</em>在不同语言之间可以不同，所以我们必须给所有参数命名。</p><p>这也意味着可能存在明确<em>错误</em>的翻译——如果源文本中出现的某个参数没有出现在译文中，游戏里就显示不出来！这就是我们前面提到的翻译测试之一：翻译者开 PR 时，游戏会通过 Github Actions 构建并测试，有失败会通知。目前从 action 输出中找到警告失败的那段文本主要由开发者来做，但我希望有一天也能自动化。</p><p>因此，要翻译 &quot;[Temple] has been built in [Rome]&quot; 这样的文本，我们需要：</p><ul><li>找到相关翻译（做法是擦除输入中方括号之间的所有文本，找到匹配的翻译文本）</li><li>把占位符名映射到输入文本（construction = Temple, cityName = Rome）</li><li>把译文中的占位符替换为翻译后的输入文本（在 <code>[cityName] ha costruito [construction]</code> 中，把 &quot;[cityName]&quot; 替换为 &quot;Rome&quot; 的翻译，把 &quot;[construction]&quot; 替换为 &quot;Temple&quot; 的翻译）</li></ul><h3 id="翻译模组数据" tabindex="-1">翻译模组数据 <a class="header-anchor" href="#翻译模组数据" aria-label="Permalink to &quot;翻译模组数据&quot;">​</a></h3><p>翻译生成从&quot;一个规则集&quot;读取信息，即定义游戏对象的那组 json。 每个模组也是一个规则集，要么替换要么添加游戏定义的基础规则集。 这意味着我们为基础游戏做的同一套翻译生成也可以应用到模组上，因此每个模组制作者都可以（在游戏内）决定为自己的模组生成翻译文件；由于模组作为发布方法论的一部分上传到 Github 以广泛分发，翻译者就能用翻译 Unciv 基础规则集完全相同的方式来翻译这些文件。</p>',25)])])}const q=e(n,[["render",r]]);export{m as __pageData,q as default};
